// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';
import { createCollection, createUser, createCollectionTransfer, getCollectionsList, deleteUser, deleteCollection } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const collectionsPostResponse = await createCollection(client, URL_localhost, headers, "tb-transfer-guard");
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'name').toBe("tb-transfer-guard");
    expect(getResponseValue(collectionsPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    const collectionId = getResponseValue(collectionsPostResponse, "response.id");
    const ownerId = getResponseValue(collectionsPostResponse, "response.ownerId");
    expect(ownerId, 'ownerId').toBeGreaterThan(0);
    expect(getResponseValue(collectionsPostResponse, "response.members").length, 'members').toBe(0);

    const usersPostResponse = await createUser(client, URL_localhost, headers, "TB Outsider", "tboutsider", "tboutsider@example.com", "tboutsiderpassword123");
    // An admin-authenticated create returns the narrow admin shape: id, username, email,
    // emailVerified, subscriptions, createdAt — no name field.
    expect(getResponseValue(usersPostResponse, "response.username"), 'username').toMatch(/^tboutsider-\d+$/);
    expect(getResponseValue(usersPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    const outsiderUserId = getResponseValue(usersPostResponse, "response.id");
    expect(outsiderUserId, 'the outsider is a different account from the owner').not.toBe(ownerId);

    // A transfer body carrying no toUserId is refused before anything is written.
    const transferPostRequestBody: string = `{
        "note": "toUserId deliberately omitted"
    }`;
    const transferPostResponse = await createCollectionTransfer(client, URL_localhost, headers, collectionId, transferPostRequestBody, 400);
    expect(getResponseValue(transferPostResponse, "response"), 'response').toBe("toUserId is required.");

    // The PR description states: "a toUserId who is not already a member of the collection
    // returns HTTP 404". transfer.ts:43 answers 400 instead, so this is the requirement
    // conflict; it turns green once the handler answers 404 for an ineligible target.
    const transferPost1RequestBody: string = `{
        "toUserId": ${outsiderUserId}
    }`;
    const transferPost1Response = await createCollectionTransfer(client, URL_localhost, headers, collectionId, transferPost1RequestBody, 404);
    expect(transferPost1Response.statusCode, 'status code').toBe(404);
    expect(getResponseValue(transferPost1Response, "response.ownerId"), 'a refused transfer returns no collection').toBeNull();

    // Neither refusal may have moved ownership: the collection is still the caller's.
    const collectionsGetResponse = await getCollectionsList(client, URL_localhost, headers);
    const owned = getResponseValue(collectionsGetResponse, "response").filter((c: any) => c.id === collectionId);
    expect(owned.length, 'the collection is still listed for the caller').toBe(1);
    expect(owned[0].ownerId, 'ownerId is unchanged by the refused transfers').toBe(ownerId);
    expect(owned[0].name, 'name').toBe("tb-transfer-guard");

    await deleteUser(client, URL_localhost, headers, outsiderUserId);
    await deleteCollection(client, URL_localhost, headers, collectionId);
});
